mapper.select:
SELECT config_id, config_name, config_code, config_value, config_type, description, status, create_by, create_time, update_by, update_time FROM finance_config
AND config_name LIKE '%' || #{params.configName} || '%'
AND config_code = #{params.configCode}
AND config_type = #{params.configType}
AND status = #{params.status}
ORDER BY create_time DESC
